SELECT 
FROM ainer_org_engagement
WHERE directory_id = #{directoryId} AND id = #{id}

SELECT 
FROM ainer_org_engagement
WHERE directory_id = #{directoryId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS(
    SELECT 1 FROM ainer_org_engagement
    WHERE directory_id = #{directoryId}
      AND (subject_issuer || ':' || subject_id) = #{subjectKey}
      AND status <> 'REVOKED'
      AND tstzrange(valid_from, valid_until) && tstzrange(#{validFrom}, #{validUntil})
)

